package org.fireflyframework.koinon.sdk.api;
import java.util.*;
import java.util.concurrent.CompletableFuture;
import org.fireflyframework.koinon.sdk.*;
import org.fireflyframework.koinon.sdk.internal.Transport;
import org.fireflyframework.koinon.sdk.model.*;

public final class DatasetsApi {
private final Transport transport; private final String prefix;
public DatasetsApi(Transport transport,String tenantId){this.transport=Objects.requireNonNull(transport);this.prefix="/tenants/"+Transport.id(tenantId);}
public DatasetSchema schema(String datasetId,RequestOptions options){Objects.requireNonNull(options);return transport.json("GET",prefix+"/datasets/"+Transport.id(datasetId)+"/schema",null,options,transport.type(DatasetSchema.class));}
public DatasetSchema schema(String datasetId){return schema(datasetId,RequestOptions.defaults());}
public CompletableFuture<DatasetSchema> schemaAsync(String datasetId,RequestOptions options){Objects.requireNonNull(options);return transport.jsonAsync("GET",prefix+"/datasets/"+Transport.id(datasetId)+"/schema",null,options,transport.type(DatasetSchema.class));}
public CompletableFuture<DatasetSchema> schemaAsync(String datasetId){return schemaAsync(datasetId,RequestOptions.defaults());}
public ContentUpdate reingestTable(String datasetId,String tableId,TableReingestInput input,String expectedRevision,RequestOptions options){Objects.requireNonNull(options);Objects.requireNonNull(input);options=options.ifMatch(ApiSupport.precondition(expectedRevision));return transport.json("POST",prefix+"/datasets/"+Transport.id(datasetId)+"/tables/"+Transport.id(tableId)+"/reingest",input,options,transport.type(ContentUpdate.class));}
public ContentUpdate reingestTable(String datasetId,String tableId,TableReingestInput input,String expectedRevision){return reingestTable(datasetId,tableId,input,expectedRevision,RequestOptions.defaults());}
public CompletableFuture<ContentUpdate> reingestTableAsync(String datasetId,String tableId,TableReingestInput input,String expectedRevision,RequestOptions options){Objects.requireNonNull(options);Objects.requireNonNull(input);options=options.ifMatch(ApiSupport.precondition(expectedRevision));return transport.jsonAsync("POST",prefix+"/datasets/"+Transport.id(datasetId)+"/tables/"+Transport.id(tableId)+"/reingest",input,options,transport.type(ContentUpdate.class));}
public CompletableFuture<ContentUpdate> reingestTableAsync(String datasetId,String tableId,TableReingestInput input,String expectedRevision){return reingestTableAsync(datasetId,tableId,input,expectedRevision,RequestOptions.defaults());}
public ContentUpdate replaceTable(String datasetId,String tableId,TableReplacement input,String expectedRevision,RequestOptions options){Objects.requireNonNull(options);Objects.requireNonNull(input);options=options.ifMatch(ApiSupport.precondition(expectedRevision));return transport.multipart("POST",prefix+"/datasets/"+Transport.id(datasetId)+"/tables/"+Transport.id(tableId)+"/content",input.file(),"file",input.mediaType(),Map.of(),options,transport.type(ContentUpdate.class));}
public ContentUpdate replaceTable(String datasetId,String tableId,TableReplacement input,String expectedRevision){return replaceTable(datasetId,tableId,input,expectedRevision,RequestOptions.defaults());}
public CompletableFuture<ContentUpdate> replaceTableAsync(String datasetId,String tableId,TableReplacement input,String expectedRevision,RequestOptions options){Objects.requireNonNull(options);Objects.requireNonNull(input);options=options.ifMatch(ApiSupport.precondition(expectedRevision));return transport.multipartAsync("POST",prefix+"/datasets/"+Transport.id(datasetId)+"/tables/"+Transport.id(tableId)+"/content",input.file(),"file",input.mediaType(),Map.of(),options,transport.type(ContentUpdate.class));}
public CompletableFuture<ContentUpdate> replaceTableAsync(String datasetId,String tableId,TableReplacement input,String expectedRevision){return replaceTableAsync(datasetId,tableId,input,expectedRevision,RequestOptions.defaults());}
public DatasetFileAppendResult appendFile(String datasetId,DatasetFileUpload input,String idempotencyKey,RequestOptions options){Objects.requireNonNull(options);options=options.idempotencyKey(Objects.requireNonNull(idempotencyKey));Objects.requireNonNull(input);return transport.multipart("POST",prefix+"/datasets/"+Transport.id(datasetId)+"/files",input.file(),"file",input.mediaType(),Map.of(),options,transport.type(DatasetFileAppendResult.class));}
public DatasetFileAppendResult appendFile(String datasetId,DatasetFileUpload input,String idempotencyKey){return appendFile(datasetId,input,idempotencyKey,RequestOptions.defaults());}
public CompletableFuture<DatasetFileAppendResult> appendFileAsync(String datasetId,DatasetFileUpload input,String idempotencyKey,RequestOptions options){Objects.requireNonNull(options);options=options.idempotencyKey(Objects.requireNonNull(idempotencyKey));Objects.requireNonNull(input);return transport.multipartAsync("POST",prefix+"/datasets/"+Transport.id(datasetId)+"/files",input.file(),"file",input.mediaType(),Map.of(),options,transport.type(DatasetFileAppendResult.class));}
public CompletableFuture<DatasetFileAppendResult> appendFileAsync(String datasetId,DatasetFileUpload input,String idempotencyKey){return appendFileAsync(datasetId,input,idempotencyKey,RequestOptions.defaults());}
public TableProvenance tableProvenance(String datasetId,String tableId,TableProvenanceFilter filter,RequestOptions options){Objects.requireNonNull(options);options=Objects.requireNonNull(filter).applyTo(options);return transport.json("GET",prefix+"/datasets/"+Transport.id(datasetId)+"/tables/"+Transport.id(tableId)+"/provenance",null,options,transport.type(TableProvenance.class));}
public TableProvenance tableProvenance(String datasetId,String tableId,TableProvenanceFilter filter){return tableProvenance(datasetId,tableId,filter,RequestOptions.defaults());}
public CompletableFuture<TableProvenance> tableProvenanceAsync(String datasetId,String tableId,TableProvenanceFilter filter,RequestOptions options){Objects.requireNonNull(options);options=Objects.requireNonNull(filter).applyTo(options);return transport.jsonAsync("GET",prefix+"/datasets/"+Transport.id(datasetId)+"/tables/"+Transport.id(tableId)+"/provenance",null,options,transport.type(TableProvenance.class));}
public CompletableFuture<TableProvenance> tableProvenanceAsync(String datasetId,String tableId,TableProvenanceFilter filter){return tableProvenanceAsync(datasetId,tableId,filter,RequestOptions.defaults());}
public TableSnapshotPage tableSnapshots(String datasetId,String tableId,TableSnapshotFilter filter,RequestOptions options){Objects.requireNonNull(options);options=Objects.requireNonNull(filter).applyTo(options);return transport.json("GET",prefix+"/datasets/"+Transport.id(datasetId)+"/tables/"+Transport.id(tableId)+"/snapshots",null,options,transport.type(TableSnapshotPage.class));}
public TableSnapshotPage tableSnapshots(String datasetId,String tableId,TableSnapshotFilter filter){return tableSnapshots(datasetId,tableId,filter,RequestOptions.defaults());}
public TableSnapshotPage tableSnapshots(String datasetId,String tableId){return tableSnapshots(datasetId,tableId,TableSnapshotFilter.empty(),RequestOptions.defaults());}
public CompletableFuture<TableSnapshotPage> tableSnapshotsAsync(String datasetId,String tableId,TableSnapshotFilter filter,RequestOptions options){Objects.requireNonNull(options);options=Objects.requireNonNull(filter).applyTo(options);return transport.jsonAsync("GET",prefix+"/datasets/"+Transport.id(datasetId)+"/tables/"+Transport.id(tableId)+"/snapshots",null,options,transport.type(TableSnapshotPage.class));}
public CompletableFuture<TableSnapshotPage> tableSnapshotsAsync(String datasetId,String tableId,TableSnapshotFilter filter){return tableSnapshotsAsync(datasetId,tableId,filter,RequestOptions.defaults());}
public CompletableFuture<TableSnapshotPage> tableSnapshotsAsync(String datasetId,String tableId){return tableSnapshotsAsync(datasetId,tableId,TableSnapshotFilter.empty(),RequestOptions.defaults());}
public TableCoordinateManifest tableCoordinates(String datasetId,String tableId,TableCoordinateFilter filter,RequestOptions options){Objects.requireNonNull(options);options=Objects.requireNonNull(filter).applyTo(options);return transport.json("GET",prefix+"/datasets/"+Transport.id(datasetId)+"/tables/"+Transport.id(tableId)+"/coordinates",null,options,transport.type(TableCoordinateManifest.class));}
public TableCoordinateManifest tableCoordinates(String datasetId,String tableId,TableCoordinateFilter filter){return tableCoordinates(datasetId,tableId,filter,RequestOptions.defaults());}
public CompletableFuture<TableCoordinateManifest> tableCoordinatesAsync(String datasetId,String tableId,TableCoordinateFilter filter,RequestOptions options){Objects.requireNonNull(options);options=Objects.requireNonNull(filter).applyTo(options);return transport.jsonAsync("GET",prefix+"/datasets/"+Transport.id(datasetId)+"/tables/"+Transport.id(tableId)+"/coordinates",null,options,transport.type(TableCoordinateManifest.class));}
public CompletableFuture<TableCoordinateManifest> tableCoordinatesAsync(String datasetId,String tableId,TableCoordinateFilter filter){return tableCoordinatesAsync(datasetId,tableId,filter,RequestOptions.defaults());}
public TableCoordinateSelection tableCoordinateCells(String datasetId,String tableId,CoordinateCellRequest input,RequestOptions options){Objects.requireNonNull(options);Objects.requireNonNull(input);return transport.json("POST",prefix+"/datasets/"+Transport.id(datasetId)+"/tables/"+Transport.id(tableId)+"/coordinates/cells",input,options,transport.type(TableCoordinateSelection.class));}
public TableCoordinateSelection tableCoordinateCells(String datasetId,String tableId,CoordinateCellRequest input){return tableCoordinateCells(datasetId,tableId,input,RequestOptions.defaults());}
public CompletableFuture<TableCoordinateSelection> tableCoordinateCellsAsync(String datasetId,String tableId,CoordinateCellRequest input,RequestOptions options){Objects.requireNonNull(options);Objects.requireNonNull(input);return transport.jsonAsync("POST",prefix+"/datasets/"+Transport.id(datasetId)+"/tables/"+Transport.id(tableId)+"/coordinates/cells",input,options,transport.type(TableCoordinateSelection.class));}
public CompletableFuture<TableCoordinateSelection> tableCoordinateCellsAsync(String datasetId,String tableId,CoordinateCellRequest input){return tableCoordinateCellsAsync(datasetId,tableId,input,RequestOptions.defaults());}
public TableRowRangePage tableCoordinateRows(String datasetId,String tableId,TableCoordinatePageFilter filter,RequestOptions options){Objects.requireNonNull(options);options=Objects.requireNonNull(filter).applyTo(options);return transport.json("GET",prefix+"/datasets/"+Transport.id(datasetId)+"/tables/"+Transport.id(tableId)+"/coordinates/rows",null,options,transport.type(TableRowRangePage.class));}
public TableRowRangePage tableCoordinateRows(String datasetId,String tableId,TableCoordinatePageFilter filter){return tableCoordinateRows(datasetId,tableId,filter,RequestOptions.defaults());}
public CompletableFuture<TableRowRangePage> tableCoordinateRowsAsync(String datasetId,String tableId,TableCoordinatePageFilter filter,RequestOptions options){Objects.requireNonNull(options);options=Objects.requireNonNull(filter).applyTo(options);return transport.jsonAsync("GET",prefix+"/datasets/"+Transport.id(datasetId)+"/tables/"+Transport.id(tableId)+"/coordinates/rows",null,options,transport.type(TableRowRangePage.class));}
public CompletableFuture<TableRowRangePage> tableCoordinateRowsAsync(String datasetId,String tableId,TableCoordinatePageFilter filter){return tableCoordinateRowsAsync(datasetId,tableId,filter,RequestOptions.defaults());}
public TableColumnBindingPage tableCoordinateColumns(String datasetId,String tableId,TableCoordinatePageFilter filter,RequestOptions options){Objects.requireNonNull(options);options=Objects.requireNonNull(filter).applyTo(options);return transport.json("GET",prefix+"/datasets/"+Transport.id(datasetId)+"/tables/"+Transport.id(tableId)+"/coordinates/columns",null,options,transport.type(TableColumnBindingPage.class));}
public TableColumnBindingPage tableCoordinateColumns(String datasetId,String tableId,TableCoordinatePageFilter filter){return tableCoordinateColumns(datasetId,tableId,filter,RequestOptions.defaults());}
public CompletableFuture<TableColumnBindingPage> tableCoordinateColumnsAsync(String datasetId,String tableId,TableCoordinatePageFilter filter,RequestOptions options){Objects.requireNonNull(options);options=Objects.requireNonNull(filter).applyTo(options);return transport.jsonAsync("GET",prefix+"/datasets/"+Transport.id(datasetId)+"/tables/"+Transport.id(tableId)+"/coordinates/columns",null,options,transport.type(TableColumnBindingPage.class));}
public CompletableFuture<TableColumnBindingPage> tableCoordinateColumnsAsync(String datasetId,String tableId,TableCoordinatePageFilter filter){return tableCoordinateColumnsAsync(datasetId,tableId,filter,RequestOptions.defaults());}
}
